def _get_deepest_paren_level(paren_string: str) -> int:
    """ Input to this function is a string represented a single group for nested parentheses.
    For this group, output the deepest level of nesting of parentheses.
    E.g. ((()) has maximum one level of nesting while (() has no nesting at all.

    >>> _get_deepest_paren_level('(()')
    1
    """
    group_paren_counter = 0
    for character in paren_string:
        if character == '(':
            group_paren_counter += 1
        elif character == ')':
            if group_paren_counter == 0:
                return 0
            else:
                group_paren_counter -= 1
    return group_paren_counter


