def fibonacci_number(number: int) -> int:
    """ Given an integer 'number', return the number in the Fibonacci
    sequence up to the first integer less than 'number'.
    """
    if number <= 0:
        return 0

    previous_number = 0
    current_number = 1

    while previous_number + current_number <= number:
        next_number = previous_number + current_number
        previous_number = current_number
        current_number = next_number

    return current_number

